mapper.select:
SELECT c.*, w.warehouse_name, u.real_name as operator_name FROM biz_stock_check c INNER JOIN biz_warehouse w ON c.warehouse_id = w.id LEFT JOIN sys_user u ON c.operator_id = u.id WHERE 1=1
AND c.check_no LIKE CONCAT('%', #{checkNo}, '%')
AND c.warehouse_id = #{warehouseId}
AND c.status = #{status}
ORDER BY c.create_time DESC
